<?php
declare(strict_types=1);

function fc16_support_schema(App $app):void {
    $app->db->exec('CREATE TABLE IF NOT EXISTS fisitaap_support_r16 (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference VARCHAR(24) NOT NULL UNIQUE,tenant_id BIGINT UNSIGNED NULL,actor_id BIGINT UNSIGNED NULL,verified TINYINT NOT NULL DEFAULT 0,store_name VARCHAR(150) NOT NULL,store_url VARCHAR(300) NOT NULL DEFAULT "",contact_name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL DEFAULT "",phone VARCHAR(40) NOT NULL DEFAULT "",subject VARCHAR(180) NOT NULL,description TEXT NOT NULL,conversation TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT "new",revision INT NOT NULL DEFAULT 0,request_key CHAR(64) NOT NULL UNIQUE,payload_hash CHAR(64) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX queue(status,id),INDEX business(tenant_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
    $app->db->exec('CREATE TABLE IF NOT EXISTS fisitaap_support_events_r16 (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,status VARCHAR(20) NOT NULL,note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX ticket(ticket_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
}
function fc16_support_offer(string $message,array $history=[]):bool {
    $q=fc_domain_text($message);
    if(preg_match('/ticket|caso de soporte|soporte humano|asesor humano|hablar con (?:una persona|alguien)|sigue (?:igual|sin|fallando)|no (?:funciono|se (?:arreglo|resolvio)|logro|sirvio|pude resolver|pude solucionar)|aun (?:falla|no)|todavia (?:falla|no)|no me (?:funciona|ayuda)/u',$q))return true;
    if(in_array($q,['no','nada','igual','tampoco','todavia no','aun no'],true))foreach(array_slice($history,-6) as $h)if(!empty($h['in_scope'])&&preg_match('/no imprim|error|falla|no funciona|no abre|no carga/u',fc_domain_text((string)$h['text'])))return true;
    return false;
}
function fc16_support_clean(string $text,int $max=4000):string {
    $text=mb_substr($text,0,$max);
    $text=preg_replace('/\b(?:sk-[A-Za-z0-9_-]{12,}|Bearer\s+[A-Za-z0-9_.-]{10,})/u','[dato secreto omitido]',$text)??'';
    return preg_replace('/((?:contrase[nñ]a|password|api[_ -]?key|token|clave secreta)\s*[:=]\s*)\S+/iu','$1[omitido]',$text)??'';
}
function fc16_support_create(App $app,?array $user,array $body,array $thread):array {
    if(!fc16_ready($app))throw new DomainException('El maestro debe instalar primero la actualización de soporte.');
    if(!empty($GLOBALS['demo_context']))throw new DomainException('La demostración no crea tickets reales. Abre la web oficial para solicitar soporte.');
    $request=fc16_text($body['request_id']??'',64,true);if(!preg_match('/^[a-zA-Z0-9-]{16,64}$/D',$request))throw new DomainException('Referencia de solicitud inválida.');
    $name=fc16_text($body['contact_name']??'',150,true);$email=fc16_text($body['email']??'',190);$phone=fc16_text($body['phone']??'',40);
    if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new DomainException('Escribe un correo válido.');
    if($phone!==''&&!preg_match('/^[+0-9 ()-]{7,40}$/D',$phone))throw new DomainException('Escribe un teléfono de contacto válido.');
    if($email===''&&$phone==='')throw new DomainException('Indica teléfono o correo para que soporte pueda contactarte.');
    $store=fc16_text($body['store_name']??'',150,true);$link=fc16_text($body['store_url']??'',300);$subject=fc16_text($body['subject']??'',180,true);$description=fc16_text($body['description']??'',4000,true);
    if(mb_strlen($description)<12)throw new DomainException('Describe el problema con un poco más de detalle.');
    if($link!==''&&(!filter_var($link,FILTER_VALIDATE_URL)||!in_array(parse_url($link,PHP_URL_SCHEME),['https','http'],true)||parse_url($link,PHP_URL_USER)||parse_url($link,PHP_URL_PASS)||parse_url($link,PHP_URL_QUERY)||parse_url($link,PHP_URL_FRAGMENT)))throw new DomainException('Comparte el enlace público de la tienda sin códigos, parámetros ni datos de acceso.');
    $tenant=null;$verified=false;
    if($user&&$user['role']==='tenant_admin'&&!$user['force_password_change']){$tenant=$app->one('SELECT id,name,slug FROM tenants WHERE id=? AND is_active=1',[$user['tenant_id']]);$verified=(bool)$tenant;if($tenant){$store=$tenant['name'];$link=url($tenant['slug']);}}
    $history=[];foreach(array_slice($thread['history']??[],-8) as $row)if(!empty($row['in_scope']))$history[]=($row['role']==='user'?'Solicitante: ':'FISIChat: ').fc16_support_clean((string)$row['text'],1000);
    $description=fc16_support_clean($description);$subject=fc16_support_clean($subject,180);$conversation=mb_substr(implode("\n\n",$history),0,8000);
    $key=hash_hmac('sha256',session_id().'|'.$request,$app->config['app_key']);$payload=hash('sha256',fc16_json([$name,$email,$phone,$store,$link,$subject,$description,$tenant['id']??null]));
    $prior=$app->one('SELECT reference,payload_hash FROM fisitaap_support_r16 WHERE request_key=?',[$key]);if($prior){if(!hash_equals($prior['payload_hash'],$payload))throw new DomainException('Esa referencia ya se usó para otro caso. Inicia una solicitud nueva.');return ['reference'=>$prior['reference'],'reply'=>'Tu ticket '.$prior['reference'].' ya quedó registrado. El equipo de FISITAAP lo verá con tus datos de contacto.'];}
    if(!rate_limit_persistent($app,'support_r16',client_identity((string)($user['id']??'public')),5,3600))throw new DomainException('Ya recibimos varias solicitudes. Espera antes de abrir otro caso.');
    $app->db->beginTransaction();try{
        $ref='SOP-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(4)));
        $app->exec('INSERT INTO fisitaap_support_r16(reference,tenant_id,actor_id,verified,store_name,store_url,contact_name,email,phone,subject,description,conversation,request_key,payload_hash) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$ref,$tenant['id']??null,$user['id']??null,$verified?1:0,$store,$link,$name,$email,$phone,$subject,$description,$conversation,$key,$payload]);$id=(int)$app->db->lastInsertId();
        $app->exec('INSERT INTO fisitaap_support_events_r16(ticket_id,user_id,status,note) VALUES(?,?,"new","Solicitud recibida desde FISIChat de la web oficial")',[$id,$user['id']??null]);$app->db->commit();
        return ['reference'=>$ref,'reply'=>'Ticket '.$ref.' creado. El equipo de FISITAAP recibirá el caso en su panel y podrá contactarte por los datos que indicaste. No necesitas compartir contraseñas ni códigos.'];
    }catch(Throwable $error){if($app->db->inTransaction())$app->db->rollBack();if($error instanceof PDOException&&$error->getCode()==='23000'){$prior=$app->one('SELECT reference,payload_hash FROM fisitaap_support_r16 WHERE request_key=?',[$key]);if($prior&&hash_equals($prior['payload_hash'],$payload))return ['reference'=>$prior['reference'],'reply'=>'Ticket '.$prior['reference'].' registrado.'];}throw $error;}
}
function fc16_support_states():array {return ['new'=>'Nuevo','in_progress'=>'En atención','resolved'=>'Resuelto','closed'=>'Cerrado'];}
function fc16_support_context(App $app):array {
    if(!fc16_ready($app))return ['pendientes'=>0,'tickets'=>[]];
    return ['pendientes'=>(int)$app->one('SELECT COUNT(*) n FROM fisitaap_support_r16 WHERE status IN("new","in_progress")')['n'],'tickets'=>$app->all('SELECT reference,store_name,verified,subject,status,created_at FROM fisitaap_support_r16 WHERE status IN("new","in_progress") ORDER BY id DESC LIMIT 10')];
}
function fc16_support_page(App $app,array $user):void {
    $fresh=$app->one('SELECT id FROM users WHERE id=? AND role="master" AND is_active=1 AND force_password_change=0',[$user['id']]);if(!$fresh){http_response_code(403);simple_error('Acceso restringido','Esta bandeja requiere la cuenta maestra.');return;}
    if(!fc16_ready($app)){admin_shell_start('Tickets de soporte',$user,null,'soporte');echo '<section class="card admin-card"><p>Ejecuta el actualizador R16 para preparar la bandeja de soporte.</p></section>';admin_shell_end();return;}
    $id=(int)($_GET['id']??0);$states=fc16_support_states();
    if(is_post()){
        verify_csrf();try{$status=fc16_text($_POST['status']??'',20,true);$note=fc16_support_clean(fc16_text($_POST['note']??'',2000));$rev=(int)($_POST['revision']??-1);if(!isset($states[$status]))throw new DomainException('Estado no disponible.');$app->db->beginTransaction();$row=$app->one('SELECT id,status,revision FROM fisitaap_support_r16 WHERE id=? FOR UPDATE',[$id]);if(!$row)throw new DomainException('Ticket no disponible.');if((int)$row['revision']!==$rev)throw new DomainException('Otra persona actualizó el caso. Revisa su estado antes de guardar.');if($status===$row['status']&&$note==='')throw new DomainException('Escribe una nota o cambia el estado.');$app->exec('UPDATE fisitaap_support_r16 SET status=?,revision=revision+1 WHERE id=?',[$status,$id]);$app->exec('INSERT INTO fisitaap_support_events_r16(ticket_id,user_id,status,note) VALUES(?,?,?,?)',[$id,$user['id'],$status,$note?:'Cambio de estado']);audit($app,null,(int)$user['id'],'support_update','support_ticket',$id);$app->db->commit();flash('success','Ticket actualizado.');}catch(Throwable $error){if($app->db->inTransaction())$app->db->rollBack();flash('error',$error instanceof DomainException?$error->getMessage():'No se pudo guardar el ticket.');}redirect(url('master/soporte?id='.$id));
    }
    $filter=(string)($_GET['status']??'');$q=mb_substr(trim((string)($_GET['q']??'')),0,100);$where='1=1';$args=[];if(isset($states[$filter])){$where.=' AND status=?';$args[]=$filter;}if($q!==''){$where.=' AND (store_name LIKE ? OR reference LIKE ? OR subject LIKE ?)';$args=[...$args,'%'.$q.'%','%'.$q.'%','%'.$q.'%'];}
    $rows=$app->all('SELECT id,reference,store_name,verified,subject,status,created_at FROM fisitaap_support_r16 WHERE '.$where.' ORDER BY id DESC LIMIT 200',$args);$detail=$id?$app->one('SELECT s.*,t.slug current_slug,t.name current_name FROM fisitaap_support_r16 s LEFT JOIN tenants t ON t.id=s.tenant_id WHERE s.id=?',[$id]):null;
    admin_shell_start('Tickets de soporte',$user,null,'soporte');echo '<section class="card admin-card"><form method="get" class="qa180-filter">'.field('Tienda, ticket o asunto','q',$q).'<label>Estado<select class="input" name="status"><option value="">Todos</option>';foreach($states as $key=>$label)echo '<option value="'.$key.'" '.($filter===$key?'selected':'').'>'.$label.'</option>';echo '</select></label><button class="btn primary">Filtrar</button></form></section><section class="card admin-card" data-live-region="support-list"><div class="table-wrap"><table class="table"><tr><th>Ticket</th><th>Tienda</th><th>Asunto</th><th>Estado</th><th>Fecha</th></tr>';
    foreach($rows as $r)echo '<tr><td><a href="'.e(url('master/soporte?id='.$r['id'])).'">'.e($r['reference']).'</a></td><td>'.e($r['store_name']).'<br><small>'.($r['verified']?'Cuenta verificada':'Datos declarados por solicitante').'</small></td><td>'.e($r['subject']).'</td><td>'.e($states[$r['status']]??$r['status']).'</td><td>'.e($r['created_at']).'</td></tr>';if(!$rows)echo '<tr><td colspan="5">No hay tickets con estos filtros.</td></tr>';echo '</table></div></section>';
    if($detail){echo '<section class="card admin-card fc-support-detail"><h2>'.e($detail['reference'].' · '.$detail['subject']).'</h2><p><strong>Tienda:</strong> '.e($detail['store_name']).' · '.($detail['verified']?'Asociada a su cuenta dueña verificada':'Información declarada; validar la identidad antes de intervenir la cuenta').'</p>';if($detail['store_url'])echo '<p><a href="'.e($detail['store_url']).'" target="_blank" rel="noopener noreferrer">Abrir enlace de la tienda</a></p>';echo '<p><strong>Solicitante:</strong> '.e($detail['contact_name']).'<br><strong>Correo:</strong> '.e($detail['email']?:'No indicado').'<br><strong>Teléfono:</strong> '.e($detail['phone']?:'No indicado').'</p><h3>Problema reportado</h3><p style="white-space:pre-wrap">'.e($detail['description']).'</p><details><summary>Conversación de soporte</summary><p style="white-space:pre-wrap">'.e($detail['conversation']).'</p></details><h3>Seguimiento interno</h3>';
        foreach($app->all('SELECT e.*,u.name actor_name FROM fisitaap_support_events_r16 e LEFT JOIN users u ON u.id=e.user_id WHERE ticket_id=? ORDER BY e.id',[$id]) as $event)echo '<article class="address-row"><p><strong>'.e($states[$event['status']]??$event['status']).'</strong> · '.e($event['created_at']).($event['actor_name']?' · '.e($event['actor_name']):'').'<br>'.nl2br(e($event['note'])).'</p></article>';
        echo '<form method="post">'.csrf_field().pos_hidden_148('revision',$detail['revision']).'<label>Estado<select class="input" name="status">';foreach($states as $key=>$label)echo '<option value="'.$key.'" '.($detail['status']===$key?'selected':'').'>'.$label.'</option>';echo '</select></label><label>Nota interna<textarea class="input" name="note" rows="3" maxlength="2000"></textarea></label><button class="btn primary">Guardar seguimiento</button></form></section>';
    }admin_shell_end();
}
